  "pages/rules.html": "<div id=\"page-rules\" class=\"page\">\n  <div class=\"page-header\">\n    <div class=\"page-description\">全局规则库和项目规则入口。V1 不复制 `.claude/rules` 到 `.codex`。</div>\n    <button class=\"btn-primary\" type=\"button\" onclick=\"openRuleDrawer('00-routing')\">新建规则</button>\n  </div>\n\n  <div class=\"toolbar\">\n    <div class=\"project-filter\" id=\"rule-project-filter\"></div>\n    <input type=\"search\" placeholder=\"搜索规则 / 路径\" style=\"max-width:300px\">\n    <span class=\"chip chip-purple\">Claude source</span>\n    <span class=\"chip chip-teal\">Codex direct reference</span>\n    <div class=\"toolbar-spacer\"></div>\n    <button class=\"btn-secondary\" type=\"button\" onclick=\"showToast('已模拟刷新规则库')\">刷新</button>\n  </div>\n\n  <div class=\"asset-grid compact\" id=\"rule-card-grid\"></div>\n</div>",
